/bin/zsh -lc "python3 - <<'PY'
import json
from pathlib import Path
p=json.loads(Path('input/packet.json').read_text())
def walk(v,path,depth):
    if isinstance(v,dict):
        print(path or '/', 'object',list(v))
        if depth<2:
            for k,x in v.items(): walk(x,path+'/'+k.replace('~','~0').replace('/','~1'),depth+1)
    elif isinstance(v,list):
        print(path,'array',len(v))
        if depth<2:
            for i,x in enumerate(v): walk(x,path+'/'+str(i),depth+1)
    else: print(path,repr(v))
walk(p,'',0)
PY"

