import json
from pathlib import Path
p=json.loads(Path('input/packet.json').read_text())
for k in ['company_profile','financial_availability','cash_flow','financial_indicator','income_statement','industry_member','industry_observations']:
    print('/facts/own/'+k)
    if isinstance(p['facts']['own'][k],list):
        for i,v in enumerate(p['facts']['own'][k]): print(i,json.dumps(v,ensure_ascii=False))
    else: print(json.dumps(p['facts']['own'][k],ensure_ascii=False,indent=2))
PY"

